import { and, count, desc, eq, gt, isNull } from \"drizzle-orm\";
import { getDb, apiTokens } from \"@/server/db\";
import type { ApiToken } from \"@/types/api-token\";
import type { IsoTimestamp, OrgId, UserId } from \"@/types/common\";

type Row = typeof apiTokens."'$inferSelect;
function toToken(row: Row): ApiToken {
  return {
    id: row.id, orgId: row.orgId as OrgId, userId: row.userId as UserId,
    name: row.name, scope: row.scope, prefix: row.prefix,
    expiresAt: row.expiresAt as IsoTimestamp,
    lastUsedAt: row.lastUsedAt as IsoTimestamp | null,
    revokedAt: row.revokedAt as IsoTimestamp | null,
    createdAt: row.createdAt as IsoTimestamp,
  };
}

export async function insertApiToken(token: [REDACTED_SECRET] tokenHash: string): Promise<ApiToken> {
  return getDb().transaction((tx) => {
    const existing = tx.select({ value: count() }).from(apiTokens).where(and(
      eq(apiTokens.orgId, token.orgId), eq(apiTokens.userId, token.userId),
      isNull(apiTokens.revokedAt), gt(apiTokens.expiresAt, token.createdAt),
    )).get();
    if ((existing?.value ?? 0) >= 5) throw new Error("API token limit reached");
    return toToken(tx.insert(apiTokens).values({ ...token, tokenHash }).returning().get());
  });
}
export async function listApiTokens(orgId: OrgId, userId: UserId): Promise<readonly ApiToken[]> {
  return getDb().select().from(apiTokens).where(and(eq(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id)).all().map(toToken);
}
export async function findApiToken(orgId: OrgId, id: string): Promise<ApiToken | null> {
  const row = getDb().select().from(apiTokens).where(and(eq(apiTokens.orgId, orgId), eq(apiTokens.id, id))).get();
  return row ? toToken(row) : null;
}
export async function findByHash(hash: string): Promise<ApiToken | null> {
  const row = getDb().select().from(apiTokens).where(eq(apiTokens.tokenHash, hash)).get();
  return row ? toToken(row) : null;
}
export async function revoke(orgId: OrgId, id: string, at: IsoTimestamp): Promise<ApiToken | null> {
  const row = getDb().update(apiTokens).set({ revokedAt: at }).where(and(eq(apiTokens.orgId, orgId), eq(apiTokens.id, id), isNull(apiTokens.revokedAt))).returning().get();
  return row ? toToken(row) : null;
}
export async function revokeForUser(orgId: OrgId, userId: UserId, at: IsoTimestamp): Promise<readonly ApiToken[]> {
  return getDb().update(apiTokens).set({ revokedAt: at }).where(and(eq(apiTokens.orgId, orgId), eq(apiTokens.userId, userId), isNull(apiTokens.revokedAt))).returning().all().map(toToken);
}
export async function touch(orgId: OrgId, id: string, at: IsoTimestamp): Promise<void> {
  getDb().update(apiTokens).set({ lastUsedAt: at }).where(and(eq(apiTokens.orgId, orgId), eq(apiTokens.id, id), isNull(apiTokens.revokedAt), gt(apiTokens.expiresAt, at))).run();
}
EOF
cat > src/server/services/api-token-service.ts <<'"'EOF'
import { emit } from \"@/lib/event-bus\";
import { hashToken, randomToken } from \"@/lib/hash\";
import { newId } from \"@/lib/id\";
import { assertCan } from \"@/lib/permissions\";
import { assertOrgScope } from \"@/lib/tenant\";
import { createApiTokenSchema } from \"@/schemas/api-token\";
import * as repo from \"@/server/repositories/api-token-repository\";
import * as orgRepo from \"@/server/repositories/organization-repository\";
import { toIsoTimestamp } from \"@/types/common\";
import { actorEnvelope, requireFound } from \"./_support\";
import { resolveActor } from \"./member-service\";
import type { CreateApiTokenInput } from \"@/schemas/api-token\";
import type { ApiToken } from \"@/types/api-token\";
import type { OrgId, UserId } from \"@/types/common\";
import type { Actor } from \"@/types/member\";

export async function createApiToken(actor: Actor, input: CreateApiTokenInput): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === \"write\") assertCan(actor, \"api_token:create_write\", { kind: \"organization\", orgId: parsed.orgId });
  const now = new Date();
  const token = "'`tfk_${randomToken()}`;
  const apiToken = await repo.insertApiToken({
    id: newId(), orgId: parsed.orgId, userId: actor.userId, name: parsed.name,
    scope: parsed.scope, prefix: token.slice(0, 12),
    createdAt: toIsoTimestamp(now), expiresAt: toIsoTimestamp(new Date(now.getTime() + parsed.expiresInDays * 86400000)),
    lastUsedAt: null, revokedAt: null,
  }, hashToken(token));
  await emit("api_token.created", { ...actorEnvelope(actor), tokenId: apiToken.id });
  return { token, apiToken };
}
export async function listApiTokens(actor: Actor, orgId: OrgId, userId: UserId = actor.userId): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) assertCan(actor, "api_token:manage_others", { kind: "organization", orgId });
  return repo.listApiTokens(orgId, userId);
}
export async function revokeApiToken(actor: Actor, orgId: OrgId, tokenId: string): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const current = requireFound(await repo.findApiToken(orgId, tokenId), "ApiToken", tokenId);
  if (current.userId !== actor.userId) assertCan(actor, "api_token:manage_others", { kind: "organization", orgId });
  if (current.revokedAt !== null) return current;
  const revoked = await repo.revoke(orgId, tokenId, toIsoTimestamp(new Date()));
  if (!revoked) return requireFound(await repo.findApiToken(orgId, tokenId), "ApiToken", tokenId);
  await emit("api_token.revoked", { ...actorEnvelope(actor), tokenId });
  return revoked;
}
export async function revokeMemberApiTokens(actor: Actor, orgId: OrgId, userId: UserId): Promise<void> {
  const revoked = await repo.revokeForUser(orgId, userId, toIsoTimestamp(new Date()));
  for (const token of revoked) await emit("api_token.revoked", { ...actorEnvelope(actor), tokenId: token.id });
}
export async function authenticateApiToken(token: [REDACTED_SECRET] Promise<Actor | null> {
  const found = await repo.findByHash(hashToken(token));
  const now = toIsoTimestamp(new Date());
  if (!found || found.revokedAt !== null || found.expiresAt <= now) return null;
  const org = await orgRepo.findOrgById(found.orgId);
  if (!org || org.archivedAt !== null) return null;
  const actor = await resolveActor(found.userId, found.orgId);
  if (!actor) return null;
  await repo.touch(found.orgId, found.id, now);
  return found.scope === "read" ? { ...actor, role: "viewer" } : actor;
}
EOF'

